<script setup>
import { ref, computed, onMounted, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Plus, X, Users, Check, RefreshCw, Search } from 'lucide-vue-next'
import { apiFetch } from '../lib/api.js'
import { firstError } from '../lib/subscriptions.js'
import { useCurrentUser } from '../lib/currentUser.js'
import { CAP } from '../lib/permissions.js'
const { can } = useCurrentUser(), manage = computed(() => can(CAP.MANAGE_SUBSCRIPTIONS))
const route = useRoute(), rows = ref([]), programmes = ref([]), total = ref(0), page = ref(1), last = ref(1), loading = ref(false), busy = ref(false), error = ref(''), message = ref('')
const search = ref(''), programme = ref(route.query.program || ''), status = ref(''), detail = ref(null), tab = ref('profile'), editing = ref(false), form = ref({}), initial = ref(''), discard = ref(false), state = ref(null), reason = ref('')
const attendance = ref({}), receipt = ref({}), voiding = ref(null)
const today = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` }
const date = d => d ? new Date(d.slice(0,10)+'T12:00:00').toLocaleDateString() : 'No end date'
const money = (n,c) => `${c} ${Number(n || 0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}`
const label = s => ({active:'Active',paused:'Paused',cancelled:'Cancelled',upcoming:'Not started',expired:'Expired'}[s] || s)
let loadSequence=0
async function load(reset=false) {
  if(reset) page.value=1; const sequence=++loadSequence; loading.value=true; error.value=''
  try {const r=await apiFetch('/admin/provider-members',{query:{search:search.value,program_id:programme.value||undefined,status:status.value||undefined,page:page.value}});if(!r.success)throw Error(firstError(r)); if(sequence!==loadSequence)return; rows.value=r.data.members; programmes.value=r.data.programs; total.value=r.data.total;last.value=r.data.last_page}
  catch(e){if(sequence===loadSequence)error.value=e.message}finally{if(sequence===loadSequence)loading.value=false}
}
onMounted(()=>load())
watch(()=>route.query.program,v=>{programme.value=v||'';load(true)})
function resetReceipt() {receipt.value={request_id:crypto.randomUUID(),amount:'',method:'cash',paid_on:today(),reference:'',note:''}}
async function open(id) {
  error.value=''; const r=await apiFetch(`/admin/provider-members/${id}`); if(!r.success){error.value=firstError(r);return}detail.value=r.data
  attendance.value={attended_on:today(),session:'Daily attendance',status:'present',note:''};resetReceipt();state.value=null;voiding.value=null
}
function edit(member) {
  form.value=member?{...member}:{program_id:programme.value||'',name:'',phone:'',email:'',guardian_name:'',emergency_phone:'',starts_on:today(),ends_on:'',agreed_fee:0,currency:'QAR',notes:''}
  initial.value=JSON.stringify(form.value);discard.value=false;editing.value=true;error.value=''
}
function closeEditor(){if(busy.value)return;if(initial.value!==JSON.stringify(form.value))discard.value=true;else editing.value=false}
function chooseProgramme(){const p=programmes.value.find(p=>String(p.id)===String(form.value.program_id));if(p)form.value.currency=p.currency}
async function mutate(url,body,success,method='POST') {
  if(busy.value)return false;busy.value=true;error.value=''
  try{const r=await apiFetch(url,{method,body});if(!r.success)throw Error(firstError(r));message.value=success;return r}catch(e){error.value=e.message;return false}finally{busy.value=false}
}
async function save(){const id=form.value.id;const body={...form.value,ends_on:form.value.ends_on||null,agreed_fee:Number(form.value.agreed_fee||0),currency:form.value.currency.toUpperCase()};const r=await mutate(`/admin/provider-members${id?'/'+id:''}`,body,id?'Membership updated.':'Member added.',id?'PUT':'POST');if(r){editing.value=false;await load();tab.value='profile';await open(r.data.member.id)}}
async function saveState(){const id=detail.value.member.id;if(await mutate(`/admin/provider-members/${id}/state`,{status:state.value,reason:reason.value},'Membership status updated.')){await open(id);await load()}}
async function recordAttendance(id=detail.value.member.id,quick=false){if(await mutate(`/admin/provider-members/${id}/attendance`,quick?{attended_on:today(),session:'Daily attendance',status:'present'}:attendance.value,'Attendance saved.')){if(detail.value?.member.id===id)await open(id);await load()}}
async function recordPayment(){const id=detail.value.member.id;if(await mutate(`/admin/provider-members/${id}/payments`,receipt.value,'Offline payment recorded. No money was charged.')){await open(id);await load()}}
async function voidPayment(){const id=detail.value.member.id;if(await mutate(`/admin/provider-members/${id}/payments/${voiding.value}/void`,{reason:reason.value},'Record voided. No refund was sent.')){await open(id);await load()}}
function activityNote(a){try{const d=JSON.parse(a.details||'{}');return d.reason||d.note|| (d.to?`${label(d.from)} → ${label(d.to)}`:'')}catch{return ''}}
</script>
<template>
  <div class="page pm-page">
    <header class="pm-header"><div><h1>Membership subscribers</h1><p>Your members, managed by your team. Enrolment and payment happen directly with your business.</p></div><button v-if="manage" class="btn btn-primary" @click="edit()"><Plus :size="16"/> Add member</button></header>
    <div class="pm-guidance"><Users :size="21"/><p>Add someone after they join offline. Track their membership, attendance and payments received. <strong>No Stripe connection or Bookboll customer account required.</strong></p><router-link to="/memberships">Manage listings</router-link></div>
    <p v-if="message" role="status" class="pm-success">{{ message }}</p><p v-if="error && !detail && !editing" role="alert" class="pm-error">{{ error }}</p>
    <section class="pm-register"><form class="pm-filters" @submit.prevent="load(true)"><label class="pm-search">Search members<input v-model="search" type="search" placeholder="Name, phone or email…"/></label><label>Membership<select v-model="programme" @change="load(true)"><option value="">All memberships</option><option v-for="p in programmes" :key="p.id" :value="p.id">{{ p.name }} · {{ p.venue_name }}</option></select></label><label>Status<select v-model="status" @change="load(true)"><option value="">All statuses</option><option v-for="s in ['active','upcoming','expired','paused','cancelled']" :key="s" :value="s">{{ label(s) }}</option></select></label><button class="btn btn-secondary" :disabled="loading"><Search :size="15"/> Search</button><button type="button" class="btn btn-secondary" :disabled="loading" @click="search='';programme='';status='';load(true)">Reset</button></form>
    <div class="pm-table-head"><strong>{{ total }} members</strong><span>Private to your business and authorised staff</span><button class="btn btn-secondary btn-sm" :disabled="loading" @click="load()"><RefreshCw :size="14"/> Refresh</button></div>
    <div class="table-wrap"><table><thead><tr><th>Member</th><th>Membership / venue</th><th>Membership dates</th><th>Status</th><th>Balance to collect</th><th>Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="6" class="pm-empty">Loading members…</td></tr><template v-else><tr v-for="m in rows" :key="m.id"><td><button class="pm-link" @click="tab='profile';open(m.id)">{{ m.name }}</button><small>{{ m.phone || m.email || 'No contact added' }}</small></td><td>{{ m.program_name }}<small>{{ m.venue_name }}</small></td><td>{{ date(m.starts_on) }}<small>{{ m.ends_on ? 'Until '+date(m.ends_on) : 'No end date' }}</small></td><td><span class="pm-status" :class="m.effective_status">{{ label(m.effective_status) }}</span></td><td>{{ money(Math.max(0,m.balance),m.currency) }}<small v-if="m.balance<0">Credit: {{ money(-m.balance,m.currency) }}</small></td><td class="pm-row-actions"><button class="btn btn-secondary btn-sm" @click="tab='profile';open(m.id)">Open</button><button v-if="manage && m.effective_status==='active'" class="btn btn-secondary btn-sm" :disabled="busy" @click="recordAttendance(m.id,true)"><Check :size="14"/> Present today</button></td></tr><tr v-if="!rows.length"><td colspan="6" class="pm-empty"><h2>{{ search||programme||status?'No matching members':'Start your member register' }}</h2><p>Add members who enrolled with you offline. Existing dummy subscribers are not imported.</p><button v-if="manage" class="btn btn-primary" @click="edit()">Add member</button></td></tr></template></tbody></table></div>
    <footer class="pm-pagination"><span>Page {{ page }} of {{ last }}</span><button class="btn btn-secondary btn-sm" :disabled="page<=1||loading" @click="page--;load()">Previous</button><button class="btn btn-secondary btn-sm" :disabled="page>=last||loading" @click="page++;load()">Next</button></footer></section>
    <Teleport to="body">
      <div v-if="detail && !editing" class="pm-overlay" @click.self="!busy && (detail=null)"><section class="pm-drawer" role="dialog" aria-modal="true" aria-labelledby="member-title" v-dialog="()=>{if(!busy)detail=null}"><header><div><h2 id="member-title">{{ detail.member.name }}</h2><p>{{ detail.member.program_name }}</p></div><button class="btn btn-secondary btn-icon" aria-label="Close member" :disabled="busy" @click="detail=null"><X :size="18"/></button></header>
      <nav class="pm-tabs" aria-label="Member details"><button v-for="t in ['profile','attendance','payments','activity']" :key="t" :class="{active:tab===t}" @click="tab=t">{{ {profile:'Membership',attendance:'Attendance',payments:'Offline payments',activity:'Activity'}[t] }}</button></nav>
      <div class="pm-body"><p v-if="error" role="alert" class="pm-error">{{ error }}</p>
        <template v-if="tab==='profile'"><div class="pm-status-line"><span class="pm-status" :class="detail.member.effective_status">{{ label(detail.member.effective_status) }}</span><button v-if="manage" class="btn btn-secondary btn-sm" @click="edit(detail.member)">Edit / renew dates</button></div><dl class="pm-facts"><div><dt>Membership starts</dt><dd>{{ date(detail.member.starts_on) }}</dd></div><div><dt>Membership ends</dt><dd>{{ date(detail.member.ends_on) }}</dd></div><div><dt>Phone</dt><dd>{{ detail.member.phone||'—' }}</dd></div><div><dt>Email</dt><dd>{{ detail.member.email||'—' }}</dd></div><div><dt>Guardian / contact</dt><dd>{{ detail.member.guardian_name||'—' }}</dd></div><div><dt>Emergency phone</dt><dd>{{ detail.member.emergency_phone||'—' }}</dd></div></dl><h3>Staff notes</h3><p class="pm-pre">{{ detail.member.notes||'No notes added.' }}</p>
        <div v-if="manage" class="pm-controls"><button v-if="detail.member.status==='active'" class="btn btn-secondary" @click="state='paused';reason=''">Pause membership</button><button v-if="detail.member.status!=='active'" class="btn btn-secondary" @click="state='active';reason=''">Reactivate membership</button><button v-if="detail.member.status!=='cancelled'" class="btn btn-secondary" @click="state='cancelled';reason=''">Cancel membership</button></div><form v-if="state" class="pm-form-block" @submit.prevent="saveState"><h3>{{ state==='cancelled'?'Cancel membership':state==='paused'?'Pause membership':'Reactivate membership' }}</h3><p>This updates your register only. It does not charge or refund the member. Pausing does not extend the end date.</p><label>Reason *<textarea v-model="reason" required maxlength="500" rows="2"/></label><button class="btn btn-primary" :disabled="busy">Confirm change</button><button type="button" class="btn btn-secondary" @click="state=null">Keep current status</button></form></template>
        <template v-if="tab==='attendance'"><form v-if="manage" class="pm-form-block" @submit.prevent="recordAttendance()"><h3>Record attendance</h3><div class="pm-fields"><label>Date<input v-model="attendance.attended_on" required type="date" :max="today()"/></label><label>Session / time<input v-model="attendance.session" required maxlength="100" placeholder="e.g. Beginners · 6pm"/></label><label>Attendance<select v-model="attendance.status"><option value="present">Present</option><option value="absent">Absent</option><option value="excused">Excused</option></select></label><label>Note<input v-model="attendance.note" maxlength="500"/></label></div><p>Saving the same date and session updates its attendance record.</p><button class="btn btn-primary" :disabled="busy">Save attendance</button></form><h3>Attendance history</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Session</th><th>Attendance</th></tr></thead><tbody><tr v-for="a in detail.attendance" :key="a.id"><td>{{ date(a.attended_on) }}</td><td>{{ a.session }}<small>{{ a.note }}</small></td><td>{{ a.status }}</td></tr><tr v-if="!detail.attendance.length"><td colspan="3">No attendance recorded.</td></tr></tbody></table></div></template>
        <template v-if="tab==='payments'"><div class="pm-money"><div><small>Agreed total fee</small><strong>{{ money(detail.member.agreed_fee,detail.member.currency) }}</strong></div><div><small>Recorded received</small><strong>{{ money(detail.member.received,detail.member.currency) }}</strong></div><div><small>{{ detail.member.balance<0?'Credit':'To collect' }}</small><strong>{{ money(Math.abs(detail.member.balance),detail.member.currency) }}</strong></div></div><p>Private records of money your business received offline. These do not charge customers, trigger payouts or enter Bookboll’s payment analytics.</p>
        <form v-if="manage" class="pm-form-block" @submit.prevent="recordPayment"><h3>Record money already received</h3><div class="pm-fields"><label>Amount ({{ detail.member.currency }}) *<input v-model="receipt.amount" type="number" min="0.01" max="1000000" step="0.01" required/></label><label>Received on *<input v-model="receipt.paid_on" type="date" :max="today()" required/></label><label>Method<select v-model="receipt.method"><option value="cash">Cash</option><option value="bank_transfer">Bank transfer to business</option><option value="card_terminal">Business card terminal</option><option value="other">Other offline method</option></select></label><label>Reference<input v-model="receipt.reference" maxlength="150"/></label><label class="pm-wide">Note<input v-model="receipt.note" maxlength="500"/></label></div><button class="btn btn-primary" :disabled="busy">Record offline payment</button></form>
        <div class="table-wrap"><table><thead><tr><th>Received on</th><th>Amount</th><th>Method / reference</th><th></th></tr></thead><tbody><tr v-for="p in detail.payments" :key="p.id"><td>{{ date(p.paid_on) }}</td><td>{{ money(p.amount,detail.member.currency) }}<small v-if="p.voided_at">Voided: {{ p.void_reason }}</small></td><td>{{ p.method.replaceAll('_',' ') }}<small>{{ p.reference }}</small></td><td><button v-if="manage&&!p.voided_at" class="btn btn-secondary btn-sm" @click="voiding=p.id;reason=''">Void record</button></td></tr><tr v-if="!detail.payments.length"><td colspan="4">No offline payments recorded.</td></tr></tbody></table></div><form v-if="voiding" class="pm-form-block" @submit.prevent="voidPayment"><h3>Void payment record</h3><p>This corrects the register only. Handle any refund directly with the member.</p><label>Reason *<input v-model="reason" required maxlength="500"/></label><button class="btn btn-primary" :disabled="busy">Void record</button><button type="button" class="btn btn-secondary" @click="voiding=null">Cancel</button></form></template>
        <template v-if="tab==='activity'"><h3>Changes made by your team</h3><ol class="pm-activity"><li v-for="a in detail.activity" :key="a.id"><strong>{{ a.action }}</strong><small>{{ a.actor_name||'Staff' }} · {{ new Date(a.created_at).toLocaleString() }}</small><p v-if="activityNote(a)">{{ activityNote(a) }}</p></li></ol></template>
      </div></section></div>
      <div v-if="editing" class="pm-overlay" @click.self="closeEditor"><section class="pm-drawer" role="dialog" aria-modal="true" aria-labelledby="member-editor" v-dialog="closeEditor"><header><div><h2 id="member-editor">{{ form.id?'Edit membership':'Add member' }}</h2><p>Record an enrolment arranged directly with your business.</p></div><button class="btn btn-secondary btn-icon" aria-label="Close member editor" @click="closeEditor"><X :size="18"/></button></header><form @submit.prevent="save"><div class="pm-body"><p v-if="error" role="alert" class="pm-error">{{ error }}</p><div class="pm-fields"><label class="pm-wide">Membership *<select v-model="form.program_id" required :disabled="!!form.id" @change="chooseProgramme"><option value="">Choose a membership</option><option v-for="p in programmes" :key="p.id" :value="p.id">{{ p.name }} · {{ p.venue_name }}</option></select><small>Private member management works even when a listing is not publicly visible.</small></label><label class="pm-wide">Member’s full name *<input v-model="form.name" required maxlength="150"/></label><label>Phone<input v-model="form.phone" type="tel" maxlength="40"/></label><label>Email<input v-model="form.email" type="email" maxlength="190"/></label><label>Guardian / emergency contact<input v-model="form.guardian_name" maxlength="150"/></label><label>Emergency phone<input v-model="form.emergency_phone" type="tel" maxlength="40"/></label><label>Start date *<input v-model="form.starts_on" type="date" required/></label><label>End date (optional)<input v-model="form.ends_on" type="date" :min="form.starts_on"/></label><label>Agreed total fee<input v-model="form.agreed_fee" type="number" min="0" max="1000000" step="0.01"/><small>For this membership record. Include any additional fee when extending dates.</small></label><label>Currency *<input v-model="form.currency" required minlength="3" maxlength="3" pattern="[A-Za-z]{3}"/></label><label class="pm-wide">Private staff notes<textarea v-model="form.notes" rows="3" maxlength="3000"/></label></div><div v-if="discard" class="pm-form-block">Discard unsaved changes?<button type="button" class="btn btn-secondary" @click="discard=false">Keep editing</button><button type="button" class="btn btn-secondary" @click="editing=false">Discard</button></div></div><footer class="pm-footer"><button type="button" class="btn btn-secondary" :disabled="busy" @click="closeEditor">Cancel</button><button class="btn btn-primary" :disabled="busy">{{ busy?'Saving…':form.id?'Save membership':'Add member' }}</button></footer></form></section></div>
    </Teleport>
  </div>
</template>
<style scoped>
.pm-page{color:var(--text)}.pm-header{display:flex;align-items:start;justify-content:space-between;gap:20px;margin-bottom:24px}.pm-header h1{margin:0 0 8px}.pm-header p,.pm-guidance p{margin:0;max-width:74ch;line-height:1.6;color:var(--text-muted)}.pm-guidance{display:flex;gap:16px;align-items:center;padding:18px 22px;border-left:3px solid var(--primary,#2563eb);background:var(--surface);margin-bottom:24px;font-size:13px}.pm-guidance svg{flex-shrink:0}.pm-guidance a{margin-left:auto;white-space:nowrap;color:var(--primary)}.pm-register{border:1px solid var(--border);border-radius:12px;background:var(--surface);overflow:hidden}.pm-filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap;padding:22px}.pm-filters label{flex:1;min-width:140px}.pm-filters .pm-search{flex:2}.pm-page label,.pm-drawer label{display:flex;flex-direction:column;gap:7px;font-size:12px;font-weight:600}.pm-page input,.pm-page select,.pm-drawer input,.pm-drawer select,.pm-drawer textarea{width:100%;box-sizing:border-box;background:var(--surface);color:var(--text);border:1px solid var(--border);padding:10px 12px;border-radius:7px;font:inherit;min-height:39px}.pm-table-head{display:flex;align-items:center;gap:16px;padding:15px 22px;border-top:1px solid var(--border)}.pm-table-head span{font-size:12px;color:var(--text-muted);margin-right:auto}.pm-register td,.pm-drawer td{padding:17px 16px;vertical-align:top}.pm-register th,.pm-drawer th{padding:12px 16px;font-size:12px;white-space:nowrap}.pm-register small,.pm-drawer small{display:block;font-weight:400;color:var(--text-muted);font-size:12px;line-height:1.6;margin-top:5px}.pm-link{border:0;background:none;color:var(--text);padding:0;font:inherit;font-weight:650;text-align:left;cursor:pointer}.pm-link:hover{text-decoration:underline}.pm-status{display:inline-block;border-radius:5px;background:var(--bg);border:1px solid var(--border);padding:4px 8px;font-size:12px;text-transform:none}.pm-status.active{color:#0d9488;border-color:#0d948866;background:#0d948815}.pm-status.cancelled,.pm-status.expired{color:var(--danger-ink,#d35765)}.pm-row-actions{white-space:nowrap}.pm-row-actions .btn+.btn{margin-left:7px}.pm-empty{text-align:center;padding:45px!important}.pm-empty p{color:var(--text-muted)}.pm-pagination{display:flex;gap:10px;justify-content:flex-end;align-items:center;padding:16px;border-top:1px solid var(--border);font-size:12px}.pm-pagination span{margin-right:auto}.pm-overlay{position:fixed;inset:0;z-index:2100;background:#0008;display:flex;justify-content:flex-end}.pm-drawer{width:min(720px,100%);height:100%;overflow:auto;background:var(--surface);color:var(--text);box-shadow:-10px 0 50px #0002}.pm-drawer>header{display:flex;gap:20px;justify-content:space-between;padding:25px 28px;border-bottom:1px solid var(--border)}.pm-drawer h2{font-size:22px;margin:0 0 6px}.pm-drawer h3{font-size:15px;margin:0 0 14px}.pm-drawer p{font-size:13px;line-height:1.6;color:var(--text-muted)}.pm-drawer header p{margin:0}.pm-body{padding:25px 28px}.pm-tabs{display:flex;overflow:auto;border-bottom:1px solid var(--border);padding:0 20px}.pm-tabs button{padding:16px 12px;border:0;border-bottom:2px solid transparent;white-space:nowrap;background:none;color:var(--text-muted);cursor:pointer}.pm-tabs .active{border-color:var(--primary);color:var(--primary);font-weight:650}.pm-status-line{display:flex;justify-content:space-between;align-items:center}.pm-facts,.pm-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.pm-facts{padding:24px 0;border-bottom:1px solid var(--border);margin-bottom:24px}.pm-facts dt{color:var(--text-muted);font-size:12px;margin-bottom:6px}.pm-facts dd{margin:0;overflow-wrap:anywhere;font-size:14px}.pm-pre{white-space:pre-wrap}.pm-controls{display:flex;gap:10px;flex-wrap:wrap;margin-top:25px}.pm-form-block{padding:20px;margin:20px 0;background:var(--bg);border:1px solid var(--border);border-radius:8px}.pm-form-block>.btn{margin:14px 8px 0 0}.pm-wide{grid-column:1/-1}.pm-footer{display:flex;justify-content:space-between;padding:20px 28px;border-top:1px solid var(--border);position:sticky;bottom:0;background:var(--surface)}.pm-money{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;border-bottom:1px solid var(--border);padding-bottom:20px}.pm-money strong{display:block;font-size:18px;margin-top:5px}.pm-activity{list-style:none;padding:0;margin:0}.pm-activity li{padding:18px 0;border-bottom:1px solid var(--border);font-size:14px}.pm-success{padding:12px 16px;background:#0d948815;border-left:3px solid #0d9488;font-size:13px}.pm-error{padding:12px 16px;background:#dc262615;color:var(--danger-ink,#b91c1c);border-left:3px solid #dc2626;font-size:13px}@media(max-width:700px){.pm-header{flex-direction:column}.pm-guidance{flex-wrap:wrap}.pm-guidance a{margin-left:0}.pm-table-head span{display:none}.pm-drawer>header,.pm-body{padding:20px}.pm-fields{grid-template-columns:1fr}.pm-facts{gap:20px 10px}.pm-money{grid-template-columns:1fr}.pm-row-actions .btn{display:block;margin:0 0 8px!important}}
</style>
